const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved;try{saved=JSON.parse(localStorage.getItem('soneradar-v1'))}catch{}
let zones=Array.isArray(saved?.zones)?saved.zones.filter(z=>!String(z.address||'').toLowerCase().includes('eksempelsted')).map(z=>({...z,radius:Math.min(10,Math.max(1,Number(z.radius)||5))})):[];
let selected=zones.find(z=>z.id===saved?.selected)?.id||zones[0]?.id||null,data=[],statuses=[],busy=false,epoch=0,seenEvents=saved?.seenEvents||{},mailBaseline=saved?.mailBaseline||{};
const categories=['Politi','Skogbrann','Ekstremvær','Flomfare','Skredfare'],icons={Politi:'◈',Skogbrann:'♨',Ekstremvær:'☂',Flomfare:'≈',Skredfare:'△'};
const monthKeyFormatter=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Oslo',year:'numeric',month:'2-digit'});
const monthNameFormatter=new Intl.DateTimeFormat('nb-NO',{timeZone:'Europe/Oslo',month:'long'});
function osloMonthKey(now=new Date()){const parts=Object.fromEntries(monthKeyFormatter.formatToParts(now).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));return `${parts.year}-${parts.month}`;}
let renderedMonthKey='';
let selectedCategories=new Set(categories),map,layer,searchTimer;
const zone=()=>zones.find(z=>z.id===selected)||zones[0]||null,persist=()=>localStorage.setItem('soneradar-v1',JSON.stringify({zones,selected,seenEvents,mailBaseline}));
try{const z=zone();map=L.map('map').setView(z?[z.lat,z.lon]:[64.5,15.5],z?11:5);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap',maxZoom:19}).addTo(map);layer=L.layerGroup().addTo(map)}catch{$('#map').textContent='Kartet kunne ikke lastes.'}
function modal(html){$('#dialogBody').innerHTML=html;$('#dialog').showModal()}$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close()});
function distanceKm(a,b){const r=Math.PI/180,dlat=(b.lat-a.lat)*r,dlon=(b.lon-a.lon)*r;const h=Math.sin(dlat/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dlon/2)**2;return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}
function render(){const z=zone();$('#zones').innerHTML=zones.length?zones.map(x=>`<div class="zone ${x.id===selected?'active':''}"><button class="zoneSelect" data-zone="${esc(x.id)}"><strong>${esc(x.name)}</strong><small>${esc(x.address)}</small><small>${x.radius} km radius</small></button><button class="zoneEdit" data-edit="${esc(x.id)}" aria-label="Rediger ${esc(x.name)}" title="Rediger sted">✎</button></div>`).join(''):'<div class="zoneEmpty">Legg til et sted for å hente live-data.</div>';
document.querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>{selected=b.dataset.zone;persist();epoch++;data=[];load()});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editor(zones.find(x=>x.id===b.dataset.edit)));
$('#filters').innerHTML=categories.map(c=>`<label class="filter"><input type="checkbox" data-cat="${c}" ${selectedCategories.has(c)?'checked':''}><span>${icons[c]} ${c}</span></label>`).join('');document.querySelectorAll('[data-cat]').forEach(b=>b.onchange=()=>{b.checked?selectedCategories.add(b.dataset.cat):selectedCategories.delete(b.dataset.cat);render()});
$('#status').textContent=busy?'Henter live-data …':statuses.join(' | ');$('#refreshStatus').textContent=busy?'Oppdaterer …':statuses.length?`Sist oppdatert: Kl: ${new Date().toLocaleTimeString('nb-NO',{hour:'2-digit',minute:'2-digit'})} ${new Date().toLocaleDateString('nb-NO',{day:'2-digit',month:'2-digit',year:'numeric'}).replaceAll('/','.')} · automatisk hvert 5. minutt`:'';
const now=new Date();renderedMonthKey=osloMonthKey(now);$('#monthHeading').firstChild.textContent='Registrerte hendelser innenfor sonen i '+monthNameFormatter.format(now)+' ';const list=data.filter(e=>selectedCategories.has(e.category)).sort((a,b)=>categories.indexOf(a.category)-categories.indexOf(b.category)||Date.parse(b.time)-Date.parse(a.time));$('#count').textContent=list.length;$('#events').innerHTML=list.length?list.map((e,i)=>`<details class="event eventExpandable"><summary><div class="icon">${icons[e.category]||'◉'}</div><div><h4>${esc(e.title)}</h4><p>${esc(formatTime(e.time||'Tid ikke oppgitt'))} · ${esc(e.category)}</p></div><span class="tag">${esc(e.status||e.category)} ▾</span></summary><div class="eventDetails"><p>${esc(e.description)}</p>${Array.isArray(e.updates)&&e.updates.length>1?`<p class="updateCount">${e.updates.length} oppdateringer</p>${e.updates.map(u=>`<div class="eventUpdate"><time>${esc(formatTime(u.time))}</time><p>${esc(u.text)}</p></div>`).join('')}`:''}</div></details>`).join(''):`<div class="empty">${busy?'Henter live-data …':z?'Ingen hendelser eller varsler fra kildene for valgte kategorier.':'Legg til et sted for å hente live-data.'}</div>`;
if(map){layer.clearLayers();if(z){L.circle([z.lat,z.lon],{radius:z.radius*1000,color:'#276c51',weight:2,fillOpacity:.08}).addTo(layer);L.marker([z.lat,z.lon]).bindPopup(esc(z.name)+' · sonesenter').addTo(layer);map.fitBounds(L.latLng(z.lat,z.lon).toBounds(z.radius*2400))}else map.setView([64.5,15.5],5);list.forEach(e=>{if(e.geometry)L.geoJSON(e.geometry,{style:{color:'#b54e38',weight:2,fillOpacity:.12}}).addTo(layer);else if(Number.isFinite(e.lat)&&Number.isFinite(e.lon))L.marker([e.lat,e.lon],{icon:L.divIcon({className:'eventPinWrap',html:'<span class="eventPin"></span>',iconSize:[26,34],iconAnchor:[13,32]})}).addTo(layer)})}}
function formatTime(value){const d=new Date(value);if(Number.isNaN(d.getTime()))return value;const part=o=>new Intl.DateTimeFormat('nb-NO',{...o,timeZone:'Europe/Oslo'}).format(d);return `Kl: ${part({hour:'2-digit',minute:'2-digit'})} ${part({day:'2-digit',month:'2-digit',year:'numeric'})}`}
async function sendEventNotifications(events,place,email,onBatchSent){const encoder=new TextEncoder(),notifications=events.map(e=>({id:String(e.id||''),title:String(e.title||'Varsel').slice(0,1000),description:String(e.description||'').slice(0,12000),source:String(e.source||'Ukjent').slice(0,500),time:String(e.time||'Tid ikke oppgitt').slice(0,100)})),batches=[];let batch=[];for(const event of notifications){const candidate=[...batch,event],body=JSON.stringify({to:email,place,events:candidate});if(batch.length&&(batch.length>=20||encoder.encode(body).length>90000)){batches.push(batch);batch=[event]}else batch=candidate;}if(batch.length)batches.push(batch);for(const sentBatch of batches){const response=await fetch('/api/notify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({to:email,place,events:sentBatch})}),result=await response.json();if(!response.ok||!result.sent)throw new Error(result.error||'E-postvarslet ble ikke bekreftet sendt.');onBatchSent(sentBatch);}}
const cache=new Map();async function get(url,ttl=300000){const c=cache.get(url);if(c?.retry>Date.now())throw Error('Kilden ber oss vente');if(c&&c.until>Date.now())return c.value;const r=await fetch(url,{signal:AbortSignal.timeout(18000)});if(!r.ok){const retry=r.headers.get('Retry-After'),ms=/^\d+$/.test(retry||'')?Number(retry)*1000:Math.max(60000,Date.parse(retry)-Date.now()||0);if(r.status===429||r.status===503)cache.set(url,{retry:Date.now()+ms});throw Error('HTTP '+r.status)}const value=await r.json();cache.set(url,{value,until:Date.now()+ttl});return value}
async function load(){
  const ticket=++epoch,z=zone(),requestMonth=osloMonthKey();
  if(!z){busy=false;data=[];statuses=[];render();return}
  if(requestMonth!==renderedMonthKey){data=[];statuses=[]}
  busy=true;render();
  try{
    const q=new URLSearchParams({lat:z.lat,lon:z.lon,radius:z.radius,municipality:z.municipality||'',municipalityName:z.municipalityName||''}),r=await fetch('/api/live?'+q,{signal:AbortSignal.timeout(60000)}),p=await r.json();
    if(!r.ok)throw Error(p.error||'HTTP '+r.status);
    if(ticket!==epoch)return;
    if(requestMonth!==osloMonthKey()){busy=false;data=[];statuses=[];return load()}
    data=p.events||[];statuses=(p.sources||[]).map(s=>s.name+': '+s.message);
    const ids=data.map(e=>e.id),previous=new Set(Array.isArray(seenEvents[z.id])?seenEvents[z.id]:[]),isFirstMonthLoad=mailBaseline[z.id]!==requestMonth;
    if(isFirstMonthLoad||!z.email){seenEvents[z.id]=ids;mailBaseline[z.id]=requestMonth;persist();}
    else{
      const fresh=data.filter(e=>!previous.has(e.id));
      if(fresh.length){
        try{await sendEventNotifications(fresh,z.name,z.email,batch=>{for(const event of batch)previous.add(event.id);seenEvents[z.id]=[...previous].slice(-10000);persist();});}
        catch(error){statuses.push('E-postvarsel kunne ikke sendes: '+error.message);}
      }
      seenEvents[z.id]=[...previous].slice(-10000);mailBaseline[z.id]=requestMonth;persist();
    }
  }catch(e){if(ticket!==epoch)return;data=[];statuses=['Datakildene er utilgjengelige: '+e.message]}
  busy=false;render();
}
function editor(existing){let picked=existing?{...existing}:null;modal(`<h2>${existing?'Rediger':'Nytt'} sted</h2><label for="name">Navn på stedet</label><input id="name" maxlength="40" value="${esc(existing?.name||'')}" placeholder="Navn på stedet"><label for="email">E-post for varsler</label><input id="email" type="email" maxlength="254" required value="${esc(existing?.email||'')}" placeholder="navn@eksempel.no"><label for="address">Velg sone adresse</label><input id="address" maxlength="200" autocomplete="off" value="${esc(existing?.address||'')}" placeholder="Begynn å skrive gatenavn og husnummer"><div id="results" class="results"></div><div id="searchStatus" role="status"></div><label for="radius">Varslings radius: <output id="radiusValue">${existing?.radius||5}</output> km</label><input id="radius" type="range" min="1" max="10" value="${Math.min(10,existing?.radius||5)}"><button id="save">Lagre sone</button>${existing&&zones.length>1?'<button id="delete">Slett sone</button>':''}<p id="error" role="alert"></p>`);
$('#radius').oninput=e=>$('#radiusValue').textContent=e.target.value;$('#address').oninput=()=>{picked=null;clearTimeout(searchTimer);const term=$('#address').value.trim();if(term.length<3){$('#results').innerHTML='';return}$('#searchStatus').textContent='Søker …';searchTimer=setTimeout(async()=>{try{const j=await get('https://ws.geonorge.no/adresser/v1/sok?sok='+encodeURIComponent(term)+'&treffPerSide=8&utkoordsys=4258',30000);if($('#dialog').open===false)return;$('#results').innerHTML='';for(const a of j.adresser||[]){const b=document.createElement('button');b.type='button';b.textContent=a.adressetekst+', '+a.postnummer+' '+a.poststed;b.onclick=()=>{picked={address:b.textContent,lat:a.representasjonspunkt.lat,lon:a.representasjonspunkt.lon,municipality:a.kommunenummer,municipalityName:a.kommunenavn};$('#address').value=picked.address;$('#results').innerHTML='';$('#searchStatus').textContent='Adresse valgt.'};$('#results').append(b)}$('#searchStatus').textContent=j.adresser?.length?'Velg adresse fra trefflisten.':'Ingen treff.'}catch{$('#searchStatus').textContent='Adressesøket er midlertidig utilgjengelig.'}},300)};
$('#save').onclick=()=>{const name=$('#name').value.trim(),email=$('#email').value.trim(),radius=Number($('#radius').value);if(!name||name.length>40||!email||email.length>254||!$('#email').checkValidity()){ $('#error').textContent='Skriv inn et stedsnavn på maks 40 tegn og en gyldig e-postadresse.';return}if(!picked?.lat||!picked?.lon||!picked?.municipality){$('#error').textContent='Søk etter adressen og velg et treff fra listen.';return}const z={id:existing?.id||crypto.randomUUID(),name,email,...picked,radius};if(existing)zones=zones.map(x=>x.id===z.id?z:x);else zones.push(z);selected=z.id;persist();$('#dialog').close();load()};if($('#delete'))$('#delete').onclick=()=>{zones=zones.filter(x=>x.id!==existing.id);selected=zones[0]?.id||null;persist();$('#dialog').close();load()}}
$('#add').onclick=()=>editor();
function checkMonthChange(){if(!document.hidden&&!busy&&osloMonthKey()!==renderedMonthKey)load()}
load();setInterval(()=>{if(!document.hidden&&!busy)load()},300000);setInterval(checkMonthChange,30000);
document.addEventListener?.('visibilitychange',checkMonthChange);
